PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Categories (Id INTEGER PRIMARY KEY AUTOINCREMENT, CategoryName TEXT NOT NULL, TaxRate REAL NOT NULL);
CREATE TABLE IF NOT EXISTS Vehicles (Id INTEGER PRIMARY KEY AUTOINCREMENT, Model TEXT NOT NULL, BasePrice REAL NOT NULL, Power INT NOT NULL, CategoryId INTEGER NOT NULL, FOREIGN KEY (CategoryId) REFERENCES Categories(Id));
CREATE TABLE IF NOT EXISTS MaintenanceLogs (Id INTEGER PRIMARY KEY AUTOINCREMENT, VehicleId INTEGER NOT NULL, ServiceName TEXT NOT NULL, Cost REAL NOT NULL, LogDate TEXT NOT NULL, Channel TEXT NOT NULL CHECK (Channel IN ('Online','Offline')), FOREIGN KEY (VehicleId) REFERENCES Vehicles(Id) ON DELETE CASCADE);
